questionvariables.text:
/*Defining the question*/
lower_x:rand(4);
upper_x:lower_x+rand(3)+1;
lower_y:rand(3);
upper_y:sqrt(rand(9)+lower_y);
coeff_x:rand(4)+2;
power_e:y^2-coeff_x*x;
question_expr:y*%e^(power_e);/*the function*/
int_y:int(question_expr,y,lower_y,upper_y); /*wrt y*/
int_x:int(int_y,x,lower_x,upper_x); /*wrt x*/

/*Worked solution*/
let_u:power_e;
diff_u:du=diff(let_u,y)*dy;
var_y:solve(diff_u,y)[1];
expr1:(rhs(var_y)*%e^u)*dy;
int_xx:int(int_y,x); /*wrt x*/
/*model answer*/
ta1:decimalplaces(int_x,2);

feedbackvariables.text:
/*node 1:checks for the correct answers*/

/*node 2:integrating with the same variable*/
int_y:int(question_expr,y,lower_y,upper_y); /*wrt y*/
mistake_1:int_x:int(int_y,y,lower_x,upper_x); /*wrt x*/

int_y_1:int(question_expr,x,lower_y,upper_y); /*wrt y*/
mistake_2:int_x:int(int_y_1,x,lower_x,upper_x); /*wrt x*/
